<?php $__env->startSection('content'); ?><main class="web-operations"><header><h1>Shop promotions</h1><p>In-app advertisements for buyers following your shop. One campaign per day; each buyer receives at most three promotions per week.</p></header><?php echo $__env->make('components.feature-feedback', array_diff_key(get_defined_vars(), ['__data' => 1, '__path' => 1]))->render(); ?>
<?php if(auth()->user()->role === 'seller'): ?><section class="dash-panel"><h2>Create a promotion</h2><form class="web-form" method="POST" action="<?php echo e(route('seller.promotions.store')); ?>" data-decision="seller.promotions.store" data-decision-title="Schedule this promotion?" data-decision-message="This schedules an in-app advertisement for eligible followers who allow promotions." data-decision-label="Schedule promotion"><?php echo csrf_field(); ?><label for="promotion-title">Title<input id="promotion-title" name="title" maxlength="100" value="<?php echo e(old('title')); ?>" required></label><label class="web-wide" for="promotion-message">Message<textarea id="promotion-message" name="message" maxlength="1000" required><?php echo e(old('message')); ?></textarea></label><label for="promotion-product">Product (optional)<select id="promotion-product" name="product_id"><option value="">Promote my shop</option><?php $__currentLoopData = $products; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $product): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($product->id); ?>" <?php if(old('product_id') == $product->id): echo 'selected'; endif; ?>><?php echo e($product->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label for="promotion-voucher">Voucher (optional)<select id="promotion-voucher" name="voucher_id"><option value="">No voucher</option><?php $__currentLoopData = $vouchers; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $voucher): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($voucher->id); ?>" <?php if(old('voucher_id') == $voucher->id): echo 'selected'; endif; ?>><?php echo e($voucher->code); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label for="promotion-start">Starts<input id="promotion-start" type="datetime-local" name="starts_at" value="<?php echo e(old('starts_at', now()->format('Y-m-d\TH:i'))); ?>" required></label><label for="promotion-end">Expires<input id="promotion-end" type="datetime-local" name="expires_at" value="<?php echo e(old('expires_at')); ?>" required></label><button class="dash-btn-primary" type="submit">Schedule promotion</button></form></section><?php endif; ?>
<?php $__empty_1 = true; $__currentLoopData = $promotions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $promotion): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><section class="dash-panel"><span class="web-promotion-label">ADVERTISEMENT · <?php echo e($promotion->seller->business_name); ?></span><h2><?php echo e($promotion->title); ?></h2><p><?php echo e($promotion->message); ?></p><p><?php echo e($promotion->starts_at->format('d M Y H:i')); ?> – <?php echo e($promotion->expires_at->format('d M Y H:i')); ?> · <?php echo e($promotion->cancelled_at ? 'Stopped' : ($promotion->expires_at->isPast() ? 'Expired' : 'Scheduled / active')); ?></p><?php if (! ($promotion->cancelled_at)): ?><form method="POST" action="<?php echo e(route('seller.promotions.cancel', $promotion)); ?>" data-decision="seller.promotions.cancel" data-decision-title="Stop this promotion?" data-decision-message="This stops future deliveries of this campaign." data-decision-label="Stop promotion"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="dash-btn-sm" type="submit">Stop future deliveries</button></form><?php endif; ?></section><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><section class="dash-panel"><p>No promotions created yet.</p></section><?php endif; ?><?php echo e($promotions->links()); ?></main><?php $__env->stopSection(); ?>

